package com.hhst.youtubelite.player.datasource

import com.hhst.youtubelite.extractor.Subtitle

import java.util.Locale

/**
 * Caption pick by concrete track identity (`en|manual` / `en|auto`). A
 * language-only preferred value is the pre-identity pref: human captions
 * for that language, then auto-generated.
 */
object SubtitleSelection {

    private const val AUTO = "auto"
    private const val MANUAL = "manual"

    fun key(language: String, autoGenerated: Boolean): String =
        "$language|${if (autoGenerated) AUTO else MANUAL}"

    fun languageOf(trackKey: String): String = trackKey.substringBefore('|')

    fun autoGenerated(trackKey: String): Boolean? {
        val sep = trackKey.indexOf('|')
        if (sep < 0) return null
        return trackKey.substring(sep + 1) == AUTO
    }

    private val CHINESE_VARIANTS = listOf(
        "zh-Hans", "zh-CN", "zh-Hant", "zh-TW", "zh-HK", "zh-SG", "zh-MO", "zh",
    )

    private fun isChinese(lang: String): Boolean {
        val lower = lang.lowercase()
        return lower == "zh" || lower.startsWith("zh-") || lower.startsWith("zh_")
    }

    fun select(subtitles: List<Subtitle>, trackKey: String?): List<Subtitle> {
        if (trackKey.isNullOrBlank() || subtitles.isEmpty()) return emptyList()
        val key = if (trackKey.equals(AUTO, ignoreCase = true)) {
            bestAutoTrackKey(subtitles) ?: return emptyList()
        } else {
            trackKey
        }
        val language = languageOf(key)
        val wantAuto = autoGenerated(key)
        var matches = subtitles.filter { it.languageCode.equals(language, ignoreCase = true) }
        if (matches.isEmpty() && isChinese(language)) {
            for (variant in CHINESE_VARIANTS) {
                val variantMatches = subtitles.filter { it.languageCode.equals(variant, ignoreCase = true) }
                if (variantMatches.isNotEmpty()) {
                    matches = variantMatches
                    break
                }
            }
            if (matches.isEmpty()) {
                matches = subtitles.filter { isChinese(it.languageCode) }
            }
        }
        if (matches.isEmpty()) return emptyList()
        if (wantAuto != null) {
            return matches.filter { it.autoGenerated == wantAuto }.ifEmpty { matches }.take(1)
        }
        val human = matches.filter { !it.autoGenerated }
        return human.ifEmpty { matches }.take(1)
    }

    private fun bestAutoTrackKey(subtitles: List<Subtitle>): String? {
        if (subtitles.isEmpty()) return null
        val locale = Locale.getDefault()
        val lang = locale.language.lowercase()
        val tag = locale.toLanguageTag().lowercase()

        // 1. If system locale is Chinese
        if (isChinese(lang) || isChinese(tag)) {
            for (variant in CHINESE_VARIANTS) {
                val human = subtitles.firstOrNull { it.languageCode.equals(variant, ignoreCase = true) && !it.autoGenerated }
                if (human != null) return key(human.languageCode, human.autoGenerated)
            }
            for (variant in CHINESE_VARIANTS) {
                val any = subtitles.firstOrNull { it.languageCode.equals(variant, ignoreCase = true) }
                if (any != null) return key(any.languageCode, any.autoGenerated)
            }
            val anyChinese = subtitles.firstOrNull { isChinese(it.languageCode) && !it.autoGenerated }
                ?: subtitles.firstOrNull { isChinese(it.languageCode) }
            if (anyChinese != null) return key(anyChinese.languageCode, anyChinese.autoGenerated)
        }

        // 2. Exact match with system language tag or code
        val matchTag = subtitles.firstOrNull { it.languageCode.equals(tag, ignoreCase = true) && !it.autoGenerated }
            ?: subtitles.firstOrNull { it.languageCode.equals(lang, ignoreCase = true) && !it.autoGenerated }
            ?: subtitles.firstOrNull { it.languageCode.equals(tag, ignoreCase = true) }
            ?: subtitles.firstOrNull { it.languageCode.equals(lang, ignoreCase = true) }
        if (matchTag != null) return key(matchTag.languageCode, matchTag.autoGenerated)

        // 3. Fallback to English
        val english = subtitles.firstOrNull { it.languageCode.startsWith("en", ignoreCase = true) && !it.autoGenerated }
            ?: subtitles.firstOrNull { it.languageCode.startsWith("en", ignoreCase = true) }
        if (english != null) return key(english.languageCode, english.autoGenerated)

        // 4. Fallback to first human or any subtitle
        val firstHuman = subtitles.firstOrNull { !it.autoGenerated } ?: subtitles.firstOrNull()
        return firstHuman?.let { key(it.languageCode, it.autoGenerated) }
    }

    /** Maps a stored pref (legacy language or track key) onto a persistable key. */
    fun migrate(preferred: String?, subtitles: List<Subtitle>): String? {
        if (preferred.isNullOrBlank()) return null
        val picked = select(subtitles, preferred).firstOrNull() ?: return null
        return key(picked.languageCode, picked.autoGenerated)
    }
}
